class TicketSorter {
  // properties
  private tickets: Ticket[];

  // methods
  constructor(tickets: Ticket[]) {
    this.tickets = tickets;
  }

  // methods
  sortByPrice() {
    this.tickets.sort((a, b) => {
      if (a.price < b.price) {
        return -1;
      } else if (a.price > b.price) {
        return 1;
      } else {
        return 0;
      }
    });
  }

  // methods
  sortByName() {
    this.tickets.sort((a, b) => {
      if (a.name < b.name) {
        return -1;
      } else if (a.name > b.name) {
        return 1;
      } else {
        return 0;
      }
    });
  }

  // methods
  sortByDate() {
    this.tickets.sort((a, b) => {
      if (a.date < b.date) {
        return -1;
      } else if (a.date > b.date) {
        return 1;
      } else {
        return 0;
      }
    });
  }

  // methods
  sortByType() {
    this.tickets.sort((a, b) => {
      if (a.type < b.type) {
        return -1;
      } else if (a.type > b.type) {
        return 1;
      } else {
        return 0;
      }
    });
  }

  // methods
  sortByPriceAndName() {
    this.sortByPrice();
    this.sortByName();
  }

  // methods
  sortByPriceAndDate() {
    this.sortByPrice();
    this.sortByDate();
  }

  // methods
  sortByPriceAndType() {
    this.sortByPrice();
    this.sortByType();
  }

  // methods
  sortByPriceAndDateAndType() {
    this.sortByPriceAndDate();
    this.sortByType();
  }
}

